# Summarize known solved trajectories compactly for comparison.
def glyph_data(b):
    import numpy as np
    ys,xs=np.where(np.array(b)==11)
    pts=list(zip(xs,ys))
    comps=[]
    while pts:
        stack=[pts.pop()]; comp=[]
        while stack:
            x,y=stack.pop(); comp.append((x,y))
            near=[p for p in pts if abs(p[0]-x)<=1 and abs(p[1]-y)<=1]
            for p in near: pts.remove(p); stack.append(p)
        comps.append(comp)
    out=[]
    for c in comps:
        xx=[p[0] for p in c]; yy=[p[1] for p in c]
        out.append((min(xx),min(yy),max(xx),max(yy),len(c)))
    return out
